<script>
import { bus } from "../../../app";
import PortalVue from "portal-vue";
export default {
  props:['url'],
  data () {
    return {
      
      owners:[],
      edit:[],
      product_unique_code:'',
      owner_id:'',
      start_date:'',
      end_date:'',
      editproduct_unique_code:'',
      editowner_id:'',
      editstart_date:'',
      editend_date:'',
      show:0,
      editshow:0,
      errors:[],
      errors1:[],
      success:null,
     
    }
  },

  methods:{
    getlist(page=1)
    {
       axios.get('/admin/productcode/ownershipmembers').then(response=>{
                  //console.log(response);
                  this.owners=response.data.data;
                  console.log(this.owners);
                 });
    },
    addproductowner()
    {

      this.errors=[];
                 axios.post("/admin/productowner/add",{
                    product_unique_code:this.product_unique_code,
                    owner_id:this.owner_id,
                    start_date:this.start_date,
                    end_date:this.end_date,
                    
                  }).then(response => {
                    //console.log(response);
                    this.success = response.data.message;
                    this.closeModal();
                    this.resetForm();
                    //this.getlist();
                     bus.$emit("addform", response.data.message);
                 }).catch(error => {
                   this.errors = error.response.data.errors;
                 });
    },
    productownerEdit(id)
    {
     this.editshow=1;
      axios.get('/admin/productowner/'+id+'/edit').then(response => {
       // console.log(response);
            this.edit=response.data;
            this.editowner_id=this.edit.owner_id;
            this.editstart_date=this.edit.start_date;
            this.editend_date=this.edit.end_date;
          });   
    },
    updateproductowner(id)
    {
     // alert(id);
      axios.post('/admin/productowner/'+id+'/update',{
        //product_unique_code:this.product_unique_code,
        owner_id:this.editowner_id,
        start_date:this.editstart_date,
        end_date:this.editend_date,
      }).then(response => {
        this.success    = response.data.message;
        this.close();
        this.resetedit();
        //this.getlist();
        bus.$emit("addform", response.data.message);
      }).catch(error=>{
        this.errors1=error.response.data.errors;
      });    
    },

    

    resetForm()
               {
                this.product_unique_code='';
                this.owner_id='';
                this.start_date='';
                this.end_date='';
                this.errors=[];
               },
    resetedit()
    {
      this.editproduct_unique_code='';
      this.editowner_id='';
      this.editstart_date='';
      this.editend_date='';
      this.errors1=[];      
    },
    showModal(codeid)
    {
      
      this.product_unique_code=codeid;
      this.show = 1;
     // this.reset();
    },
    
    closeModal()
    {
      this.show = 0;
      this.resetForm();
    },
    close()
    {
      this.editshow=0;
      this.resetedit();
    },
    closeMsg()
    {
      this.success=null;
    }

   

  },
  
  created()
  {   
    this.getlist();
   
  }
}
</script>

